import{_ as i,c as t,a as e,o as s}from"./index-B6pex-G_.js";const n={class:"about-page"},l={__name:"AboutView",setup(o){return(r,a)=>(s(),t("main",n,a[0]||(a[0]=[e('<section class="section project-goals" data-v-42137b38><div class="responsive-container" data-v-42137b38><h2 class="section-title" data-v-42137b38>PROJECT GOALS</h2><div class="content-box" data-v-42137b38><p class="goals-summary" data-v-42137b38> The GDCAU – Green Deal for Central Asian Universities project aims to empower universities in Central Asia as key drivers of sustainable development, aligning them with the European Green Deal framework. </p><p class="goals-summary" data-v-42137b38> The project focuses on developing and enhancing sustainability and regenerative education programs at partner universities; strengthening university ESG impact; and expanding cooperation between universities, businesses, and social actors across Eurasia. </p><p class="goals-summary" data-v-42137b38> The project’s newly-established Green Deal Center (GDC) serves as the main communication and dissemination platform for the project, as well as a gateway and training space for partnerships between green companies, universities, NGOs, and relevant governmental ministries in the EU and Central Asia; open science initiatives; local industry green assessment and training for Green Deal transition readiness; and improving EU-Central Asia cooperation around Green Deal actions and a just transition. </p></div></div></section><section class="section strategic-objectives" data-v-42137b38><div class="responsive-container" data-v-42137b38><h2 class="section-title" data-v-42137b38>STRATEGIC OBJECTIVES</h2><ol class="objectives-list" data-v-42137b38><li class="objective-item" data-v-42137b38> Strengthening institutional capacity for sustainable development strategies <ul data-v-42137b38><li data-v-42137b38>Develop new management strategies focused on ESG transformation.</li><li data-v-42137b38>Update regulations to incorporate sustainability principles.</li><li data-v-42137b38>Train leadership in strategic planning related to the Green Deal.</li><li data-v-42137b38>Enhance collaboration between universities and government bodies.</li></ul></li><li class="objective-item" data-v-42137b38> Transforming education programs and training specialists in sustainability <ul data-v-42137b38><li data-v-42137b38>Update curricula to include &quot;green skills.&quot;</li><li data-v-42137b38>Develop a joint master’s program in sustainability.</li><li data-v-42137b38>Introduce a “green skills” assessment system.</li><li data-v-42137b38>Offer continuing education in sustainability.</li></ul></li><li class="objective-item" data-v-42137b38> Expanding university-business cooperation to support ESG transformation <ul data-v-42137b38><li data-v-42137b38>Conduct ESG assessments and develop strategies.</li><li data-v-42137b38>Organize corporate training on ESG.</li><li data-v-42137b38>Encourage investment in sustainability research.</li><li data-v-42137b38>Design internships for students in collaboration with businesses.</li></ul></li><li class="objective-item" data-v-42137b38> Establishing the Green Deal Center for Evidence-based Education, Research, Innovation and Public Outreach <ul data-v-42137b38><li data-v-42137b38>Create a platform for research and knowledge exchange.</li><li data-v-42137b38>Host events on sustainability.</li><li data-v-42137b38>Engage society in environmental initiatives.</li></ul></li></ol></div></section><section class="section participants" data-v-42137b38><div class="responsive-container" data-v-42137b38><h2 class="section-title" data-v-42137b38>PARTNERS </h2><ul class="participants-list" data-v-42137b38><li data-v-42137b38>1. CONSTRUCTOR UNIVERSITY BREMEN GGMBH, BREMEN, Germany, the Coordinator;</li><li data-v-42137b38>2. SLOVENSKA POLNOHOSPODARSKA UNIVERZITA V NITRE, NITRA, Slovakia;</li><li data-v-42137b38>3. EURASIAN TECHNOLOGICAL UNIVERSITY, ALMATY, Kazakhstan;</li><li data-v-42137b38>4. KARAGANDA INDUSTRIAL UNIVERSITY, TEMIRTAU, Kazakhstan;</li><li data-v-42137b38>5. UNIVERSITAT FUR WEITERBILDUNG KREMS, KREMS, Austria;</li><li data-v-42137b38>6. BISHKEK STATE UNIVERSITY NAMED AFTER K KARASAEV, BISHKEK, Kyrgyzstan;</li><li data-v-42137b38>7. YAGSHYGELDI KAKAYEV INTERNATIONAL UNIVERSITY OF OIL AND GAS, ASHGABAT, Turkmenistan;</li><li data-v-42137b38>8. ABA ANNAYEW ADYNDAKY HALKARA ATCYLYK AKADEMIYASY ARKADAG, Turkmenistan;</li><li data-v-42137b38>9. KHOROG STATE UNIVERSITY NAMED AFTER MYONSHO NAZARSHOEV, KHOROG, Tajikistan;</li><li data-v-42137b38>10. TASHKENT KIMYO INTERNATIONAL UNIVERSITY, TASHKENT, Uzbekistan;</li><li data-v-42137b38>11. TOSHKENT IRRIGASIYA VA QISHLOQ XO JALIGINI MEXANIZATSIYALASH MUHANDISLARI INSTITUTI, TASHKENT, Uzbekistan;</li><li data-v-42137b38>12. UNIVERSITY OF CENTRAL ASIA NARYN, Kyrgyzstan;</li><li data-v-42137b38>13. UNIVERSITY OF CENTRAL ASIA KHOROG, Tajikistan;</li></ul></div></section><section class="section expected-results" data-v-42137b38><div class="responsive-container" data-v-42137b38><h2 class="section-title" data-v-42137b38>EXPECTED RESULTS</h2><ul class="results-list" data-v-42137b38><li data-v-42137b38>Active involvement of universities in the Green Deal agenda.</li><li data-v-42137b38>Improved education quality with new sustainability-focused programs.</li><li data-v-42137b38>Enhanced governance through ESG-driven strategies.</li><li data-v-42137b38>Stronger university-business partnerships.</li><li data-v-42137b38>Increased public awareness through educational campaigns.</li></ul></div></section><section class="section kpis" data-v-42137b38><div class="responsive-container" data-v-42137b38><h2 class="section-title" data-v-42137b38>MAIN KPIs</h2><ul class="kpi-list" data-v-42137b38><li data-v-42137b38>10 universities with updated governance strategies.</li><li data-v-42137b38>200 trained leaders in sustainability-focused management.</li><li data-v-42137b38>6 educational programs updated with sustainability components.</li><li data-v-42137b38>5000 students assessed for &quot;green skills.&quot;</li><li data-v-42137b38>13 continuing education programs on ESG and sustainability.</li></ul></div></section>',5)])))}},c=i(l,[["__scopeId","data-v-42137b38"]]);export{c as default};
